const BUILT = "2026-10-18T17:18:12.441Z";
const DEFAULT_UPDATE = {"repo":"higorgaeloliveira-cloud/ZenithTavern","ref":"main","mode":"ask"};

// The install folder is wherever this file lives - never the "current directory".
const ROOT = __dirname;

// ---- ZenithTavern self-update: checks the project's GitHub repo for a newer launcher ---------------------------
// Runs first, before anything is unpacked. Offline, blocked, or no newer version => it silently does nothing.
// Settings (tavern.config.json): "zenithUpdates": { "repo": "owner/name", "ref": "main", "mode": "ask" | "auto" | "off" }
async function selfUpdate(opts = {}) {
  const args = process.argv.slice(2);
  if (process.env.ZENITH_SKIP_UPDATE === '1' || args.includes('--no-update') || args.includes('--smoke-test') || args.includes('--repair')) return false;
  let cfg = {};
  try { cfg = JSON.parse(fs.readFileSync(path.join(ROOT, 'tavern.config.json'), 'utf8')); } catch { /* first run: defaults */ }
  const u = Object.assign({}, DEFAULT_UPDATE, cfg.zenithUpdates || {});
  if (u.mode === 'off' || !/^[\w.-]+\/[\w.-]+$/.test(String(u.repo)) || !/^[\w./-]+$/.test(String(u.ref))) return false;
  const base = process.env.ZENITH_UPDATE_BASE || `https://raw.githubusercontent.com/${u.repo}/${u.ref}/dist/`; // the env variable is a test hook
  const only = args.includes('--update-only');

  let meta;
  try {
    const res = await fetch(`${base}zenith-version.json?t=${Date.now()}`, { signal: AbortSignal.timeout(6000) });
    if (!res.ok) { console.log(`  • ZenithTavern update check: no update information (HTTP ${res.status}).`); return false; }
    meta = await res.json();
  } catch (e) { console.log('  • ZenithTavern update check: could not reach GitHub (' + (e && e.message || e) + '). Continuing.'); return false; }
  if (!meta || typeof meta.version !== 'string' || !/^[a-f0-9]{64}$/.test(String(meta.sha256))) return false;
  if (meta.version === VERSION || !(Date.parse(meta.built) > Date.parse(BUILT))) { if (!opts.quiet) console.log(`  ✔ ZenithTavern is up to date (v${NUMBER}).`); return false; }

  const when = new Date(meta.built).toLocaleString();
  if (u.mode !== 'auto') {
    if (!process.stdin.isTTY) { console.log('  • A newer ZenithTavern exists but this window cannot ask. Use Start-console to update.'); return false; }
    const question = `A newer ZenithTavern is available (v${NUMBER} -> v${meta.number || '?'}, ${when}). Update now?`;
    let yes;
    if (typeof opts.ask === 'function') yes = await opts.ask(question, 'Y');
    else {
      const answer = await new Promise((resolve) => {
        const rl = require('readline').createInterface({ input: process.stdin, output: process.stdout });
        const timer = setTimeout(() => { rl.close(); resolve('n'); }, 30000);
        rl.question(`\n${question} [Y/n] `, (a) => { clearTimeout(timer); rl.close(); resolve(a.trim().toLowerCase()); });
      });
      yes = !answer || /^y/.test(answer);
    }
    if (!yes) { console.log('  • Okay, staying on the current version.'); return 'declined'; }
  }

  try {
    console.log(`Updating ZenithTavern to v${meta.number || '?'} (${when})...`);
    const res = await fetch(`${base}ZenithTavern.cjs?t=${Date.now()}`, { signal: AbortSignal.timeout(90000) });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const buf = Buffer.from(await res.arrayBuffer());
    if (require('crypto').createHash('sha256').update(buf).digest('hex') !== meta.sha256) throw new Error('the download did not match its checksum');
    const text = buf.toString('utf8');
    if (!text.includes('ZenithTavern - single-file launcher') || !text.includes(JSON.stringify(meta.version))) throw new Error('the download is not a ZenithTavern launcher');
    const tmp = `${__filename}.update`;
    fs.writeFileSync(tmp, buf);
    try { fs.renameSync(tmp, __filename); } catch { fs.copyFileSync(tmp, __filename); fs.rmSync(tmp, { force: true }); }
    console.log('Updated. Starting the new version...\n');
  } catch (e) {
    console.log(`Could not update (${e && e.message || e}). Continuing with the current version.`);
    return false;
  }
  if (only) return true;
  const { spawnSync } = require('child_process');
  const r = spawnSync(process.execPath, [__filename, ...args], { stdio: 'inherit', env: { ...process.env, ZENITH_SKIP_UPDATE: '1' } });
  process.exit(r.status === null ? 1 : r.status);
}


function main() {

// src/, core/ and tools/ belong to the launcher and are refreshed when this file is newer.
// Everything else (overlay/, tavern.config.json, ...) is YOURS: written once, never overwritten.
const stampFile = path.join(ROOT, '.bundle-version');
let installed = '';
try { installed = fs.readFileSync(stampFile, 'utf8').trim(); } catch { /* first run */ }

for (const [rel, content] of Object.entries(FILES)) {
  const dest = path.join(ROOT, ...rel.split('/'));
  const managed = rel.startsWith('src/') || rel.startsWith('core/') || rel.startsWith('tools/');
  const write = managed ? (installed !== VERSION || !fs.existsSync(dest)) : !fs.existsSync(dest);
  if (!write) continue;
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  fs.writeFileSync(dest, content.startsWith('base64:') && /\.(png|jpe?g|webp|gif|ico)$/i.test(rel) ? Buffer.from(content.slice(7), 'base64') : content);
  if (rel.endsWith('.sh')) fs.chmodSync(dest, 0o755);
}

// One-time cleanups of files that older launcher versions put in the wrong place.
if (installed !== VERSION) {
  // zenith-welcome used to live in overlay/; it is launcher-managed now (core/).
  fs.rmSync(path.join(ROOT, 'overlay', 'extensions', 'zenith-welcome'), { recursive: true, force: true });
  // the launcher file was renamed from MyTavern.cjs
  if (path.basename(__filename) !== 'MyTavern.cjs') fs.rmSync(path.join(ROOT, 'MyTavern.cjs'), { force: true });
  // the project name used to default to "MyTavern"
  const cfgFile = path.join(ROOT, 'tavern.config.json');
  try {
    const text = fs.readFileSync(cfgFile, 'utf8');
    if (/"name"\s*:\s*"MyTavern"/.test(text)) fs.writeFileSync(cfgFile, text.replace(/"name"\s*:\s*"MyTavern"/, '"name": "ZenithTavern"'));
  } catch { /* no config yet */ }
}
fs.writeFileSync(stampFile, VERSION);

require(path.join(ROOT, 'src', process.argv.includes('--repair') ? 'repair.cjs' : 'launcher.cjs'));
}

// The start screen asks for the ZenithTavern update itself (src/launcher.cjs, right after "Checking for updates...").
globalThis.__zenithSelfUpdate = selfUpdate;
if (process.argv.includes('--update-only')) selfUpdate().catch(() => {}); else main();
